def selection_sort(arr):
    """
    Selection sort repeatedly finds the minimum and moves it to the front
    """
    l = len(arr)
    if l == 0:
        return arr

    for i in range(l):
        min_i = i
        for j in range(i+1, l):
            if arr[j] < arr[min_i]:
                min_i = j
        temp = arr[i]
        arr[i] = arr[min_i]
        arr[min_i] = temp

    return arr

